package main

import (
	"bytes"
	"compress/bzip2"
	"io"
)

func main() {
	// bzip2 has a reader but no writer in the standard library. This is the
	// bzip2 stream for "hello bzip2\n".
	encoded := []byte{
		0x42, 0x5a, 0x68, 0x39, 0x31, 0x41, 0x59, 0x26,
		0x53, 0x59, 0xab, 0x6b, 0xa1, 0xf1, 0x00, 0x00,
		0x02, 0xd9, 0x80, 0x00, 0x10, 0x40, 0x00, 0x10,
		0x00, 0x12, 0x64, 0xc0, 0x10, 0x20, 0x00, 0x31,
		0x00, 0xd3, 0x4d, 0x04, 0x00, 0x1e, 0xa3, 0xef,
		0x4e, 0x51, 0xa2, 0x07, 0x8b, 0xb9, 0x22, 0x9c,
		0x28, 0x48, 0x55, 0xb5, 0xd0, 0xf8, 0x80,
	}
	decoded, err := io.ReadAll(bzip2.NewReader(bytes.NewReader(encoded)))
	if err != nil {
		panic("bzip2 ReadAll failed")
	}
	if string(decoded) != "hello bzip2\n" {
		panic("bzip2 decoded mismatch")
	}
}
